class PackedCompletionResourceAdmissionTest {

	private static final int CPU = PackedCostDimensionRegistry.STEADY_STATE_CPU_WORK;

	@Test
	void exactBudgetDiagnosticRefusalPreservesTheExistingScalarIncumbent() {
		VectorBoundary boundary = firstVectorGrowth();
		PackedSearchBudget budget = new PackedSearchBudget(new PackedPlannerLimits(Long.MAX_VALUE,
				Long.MAX_VALUE, boundary.bytesBeforeGrowth()));
		try (MemoFixture fixture = fixture(budget)) {
			for (int filler = 0; filler < boundary.fillerCount(); filler++) {
				fillVector(fixture.memo(), filler);
			}
			assertEquals(boundary.bytesBeforeGrowth(), budget.retainedBytes());
			assertFalse(budget.resourceLimitReached());
			int candidates = fixture.memo().retainedCandidateCount();
			int incumbentCandidate = fixture.memo().winnerCandidateId(fixture.incumbent());
			int continuation = fixture.memo().candidateContinuationKeyId(incumbentCandidate);
			assertTrue(continuation > 0, "the same physical continuation cell already exists");
			int returned = fixture.memo()
					.offerWinnerWithMetadata(fixture.group(), fixture.memo().anyPropertyId(),
							0, 0, 0, fixture.physical(), fixture.alternativeMetadata(), 0.0d, 99.0d, 99.0d,
							new int[] { fixture.child() }, 0, 1);
			assertEquals(fixture.incumbent(), returned);
			assertEquals(7.0d, fixture.memo().winnerTotalCost(returned));
			assertEquals(incumbentCandidate, fixture.memo().winnerCandidateId(returned));
			assertEquals(continuation, fixture.memo().candidateContinuationKeyId(incumbentCandidate));
			assertEquals(candidates, fixture.memo().retainedCandidateCount(), "no zero-vector candidate is published");
			assertEquals(PackedSearchCompletionStatus.INCOMPLETE_RESOURCE_LIMIT, budget.completionStatus());
			assertEquals(boundary.bytesBeforeGrowth(), budget.retainedBytes());
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { -1, 0, 1 })
	void typedNoStateCacheUsesTheExistingEvidenceByteAdmission(int allowance) {
		StatementPattern source = pattern("admission");
		PackedPlanCache probe = new PackedPlanCache(8, 1, Long.MAX_VALUE);
		PackedPlanCache.PlanEntry original = plan(probe, source, false);
		long bytes = original.optimizationDecision().retainedQuantityBytes();
		assertTrue(bytes > 0L, "the actual typed planner must retain a nonempty sidecar without Frontier states");
		PackedPlanCache cache = new PackedPlanCache(8, 1, allowance < 0 ? 0L : bytes - allowance);
		PackedPlanCache.PlanEntry admitted = plan(cache, source, false);
		boolean retained = allowance == 0;
		assertEquals(retained ? bytes : 0L, admitted.optimizationDecision().retainedQuantityBytes());
		assertFalse(admitted.recipe().hasDetachedEvidence());
		assertFalse(admitted.supportsStaleValidation());
		assertNull(cache.findStructuralPlan(cache.fingerprint(source), context(12L), source),
				"quantity storage does not make a zero-state recipe eligible for stale Frontier validation");
		assertDiagnosticAndQuantity(admitted, retained);
		assertEquals(bytes, original.optimizationDecision().retainedQuantityBytes(),
				"admission stripping cannot mutate another immutable snapshot owner");
		PackedProviderRetainedMemory memory = new PackedProviderRetainedMemory();
		assertEquals(original.recipe().detachedQuantityBytes(), original.recipe().detachedQuantityBytes(memory));
		assertEquals(0L, original.recipe().detachedQuantityBytes(memory), "the same owned sidecar is charged once");
		assertEquals(original.recipe().detachedQuantityBytes(), original.recipe().detachedEvidenceBytes()
				- original.recipe().withoutDetachedQuantities().detachedEvidenceBytes(),
				"full retained accounting includes quantity storage once");
	}

	@Test
	void cachePressureStripsAnOlderNoStateSidecarWhileKeepingItsExecutableDiagnostics() {
		StatementPattern firstSource = pattern("first");
		PackedPlanCache probe = new PackedPlanCache(8, 1, Long.MAX_VALUE);
		long bytes = plan(probe, firstSource, false).optimizationDecision().retainedQuantityBytes();
		assertTrue(bytes > 0L);
		PackedPlanCache cache = new PackedPlanCache(8, 1, bytes);
		PackedPlanCache.PlanEntry first = plan(cache, firstSource, false);
		assertDiagnosticAndQuantity(first, true);
		StatementPattern secondSource = patternWithSubject("secondSubject", "second");
		PackedQueryFamilyIdentity firstFamily = PackedQueryFamilyIdentity.create(firstSource, null);
		PackedQueryFamilyIdentity secondFamily = PackedQueryFamilyIdentity.create(secondSource, null);
		assertNotNull(firstFamily);
		assertNotNull(secondFamily);
		assertFalse(firstFamily.matches(secondFamily), "byte pressure requires two distinct cached recipes");
		PackedPlanCache.PlanEntry second = plan(cache, secondSource, false);
		PackedPlanCache.PlanEntry retired = cache.findPlan(cache.fingerprint(firstSource), context(11L), firstSource);
		assertNotNull(retired, "byte eviction drops optional quantity authority, not the executable recipe");
		assertDiagnosticAndQuantity(retired, false);
		assertDiagnosticAndQuantity(second, true);
		assertDiagnosticAndQuantity(first, true);
		assertEquals(bytes, second.optimizationDecision().retainedQuantityBytes());
		assertEquals(0L, retired.optimizationDecision().retainedQuantityBytes());
	}

	@Test
	void changingOnlyThePredicateConstantReusesTheFamilyWithoutPublishingAConcreteEntry() {
		StatementPattern firstSource = pattern("family-first");
		StatementPattern secondSource = pattern("family-second");
		PackedPlanCache cache = new PackedPlanCache(8, 1, Long.MAX_VALUE);
		PackedPlanCache.PlanEntry first = plan(cache, firstSource, false);
		PackedQueryFamilyIdentity firstFamily = PackedQueryFamilyIdentity.create(firstSource, null);
		PackedQueryFamilyIdentity secondFamily = PackedQueryFamilyIdentity.create(secondSource, null);
		assertNotNull(firstFamily);
		assertNotNull(secondFamily);
		assertTrue(firstFamily.matches(secondFamily));
		PackedPlanningResult reused = PackedCascadesPlanner.optimize(secondSource, OptimizationGoal.root(), cache,
				context(11L), model(false));
		assertTrue(reused.exactComplete());
		assertTrue(reused.metrics().planCacheHit());
		assertEquals(secondSource.getPredicateVar().getValue(),
				((StatementPattern) reused.selectedPlan()).getPredicateVar().getValue());
		assertNull(cache.findPlan(cache.fingerprint(secondSource), context(11L), secondSource));
		assertDiagnosticAndQuantity(cache.findFamilyPlan(cache.fingerprint(secondSource), context(11L), secondFamily,
				PackedPlannerLimits.unbounded()), true);
		assertDiagnosticAndQuantity(cache.findPlan(cache.fingerprint(firstSource), context(11L), firstSource), true);
		assertDiagnosticAndQuantity(first, true);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void completedFlightDropsItsSeparateQuantityOwnershipWithoutChangingStaleEligibility(boolean frontier) {
		StatementPattern source = pattern(frontier ? "frontier-flight" : "scalar-flight");
		PackedPlanCache probe = new PackedPlanCache(8, 1, Long.MAX_VALUE);
		PackedPlanCache.PlanEntry original = plan(probe, source, frontier);
		assertTrue(original.optimizationDecision().retainedQuantityBytes() > 0L);
		assertEquals(frontier, original.supportsStaleValidation());
		PackedPlanCache cache = new PackedPlanCache(8, 1, Long.MAX_VALUE);
		PackedPlanCache.Fingerprint fingerprint = cache.fingerprint(source);
		PackedPlanCache.FlightClaim claim = cache.beginFlight(fingerprint, context(11L), source);
		assertTrue(claim.owner());
		cache.publish(claim, original, new PackedPlanCache.QueryEntry(fingerprint, context(11L), source,
				PackedQueryCacheIdentity.createPlanIdentity(source), original.query()));
		PackedPlanCache.PlanEntry completed = claim.await();
		assertNotNull(completed);
		assertEquals(frontier, completed.recipe().hasDetachedEvidence());
		assertEquals(frontier, completed.supportsStaleValidation(),
				"storage refusal is not a semantic eligibility gate");
		assertDiagnosticAndQuantity(completed, false);
		assertDiagnosticAndQuantity(cache.findPlan(fingerprint, context(11L), source), true);
		assertDiagnosticAndQuantity(original, true);
	}

	private static VectorBoundary firstVectorGrowth() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		try (MemoFixture fixture = fixture(budget)) {
			for (int filler = 0;; filler++) {
				long before = budget.retainedBytes();
				fillVector(fixture.memo(), filler);
				if (budget.retainedBytes() != before) {
					return new VectorBoundary(before, filler);
				}
			}
		}
	}

	private static void fillVector(PackedMemo memo, int filler) {
		memo.costVectors().resetBuilderToUnknown();
		memo.costVectors().setBuilderExact(CPU, 1_000.0d + filler);
		assertTrue(memo.costVectors().internBuilder() > 0);
	}

	private static MemoFixture fixture(PackedSearchBudget budget) {
		StatementPattern source = pattern("budget");
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Filter(source,
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true))));
		int count = query.relationCount();
		PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2, budget);
		int leaf = query.relChild(query.rootRelId(), 0);
		int leafGroup = memo.logicalGroupId(leaf);
		int leafPhysical = memo.addPhysicalAlternative(leafGroup, PackedRelOp.STATEMENT_PATTERN,
				query.relPayload(leaf), memo.anyPropertyId(), 7, new int[0], 0, 0);
		int leafMetadata = memo.addPhysicalMetadata(physical(5.0d, 5.0d), 1.0d, 5.0d);
		int child = memo.offerWinnerWithMetadata(leafGroup, memo.anyPropertyId(), 0, 0, 0, leafPhysical,
				leafMetadata, 0.0d, 5.0d, 5.0d, new int[0], 0, 0);
		int group = memo.logicalGroupId(query.rootRelId());
		int physical = memo.addPhysicalAlternative(group, PackedRelOp.FILTER, query.relPayload(query.rootRelId()),
				memo.anyPropertyId(), 7, new int[] { leafGroup }, 0, 1);
		int metadata = memo.addPhysicalMetadata(physical(7.0d, 7.0d), 1.0d, 7.0d);
		int incumbent = memo.offerWinnerWithMetadata(group, memo.anyPropertyId(), 0, 0, 0, physical, metadata,
				0.0d, 7.0d, 7.0d, new int[] { child }, 0, 1);
		int alternative = memo.addPhysicalMetadata(physical(7.0d, 99.0d), 1.0d, 99.0d);
		assertTrue(memo.completeUnaryCostCompletion(alternative, memo.winnerCostCompletionId(child), 99.0d) > 0,
				"an existing valid unknown-quantity programme retains the actual complete price");
		return new MemoFixture(memo, group, physical, alternative, child, incumbent);
	}

	private static PackedCostEstimate physical(double work, double price) {
		PackedCostEstimate output = new PackedCostEstimate();
		output.setRows(1.0d, price);
		output.setInclusivePhysicalCost(work, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		output.setObjectivePricePreservingPhysicalCost(price);
		return output;
	}

	private static PackedPlanCache.PlanEntry plan(PackedPlanCache cache, StatementPattern source, boolean frontier) {
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache,
				context(11L), model(frontier));
		assertTrue(result.exactComplete());
		PackedPlanCache.PlanEntry entry = cache.findPlan(cache.fingerprint(source), context(11L), source);
		assertNotNull(entry);
		return entry;
	}

	private static void assertDiagnosticAndQuantity(PackedPlanCache.PlanEntry entry, boolean known) {
		assertNotNull(entry);
		assertEquals(99.0d, entry.totalCost());
		PackedDecisionCertificate certificate = entry.recipe().decisionCertificate();
		assertTrue(certificate.candidateCount() > 0);
		for (int candidate = 0; candidate < certificate.candidateCount(); candidate++) {
			assertEquals(99.0d, certificate.candidateCostPoint(candidate, CPU));
			assertEquals(known, certificate.candidateQuantityKnown(candidate, CPU));
			if (known) {
				assertEquals(5.0d, certificate.candidateQuantityPoint(candidate, CPU));
			} else {
				for (int axis = 1; axis <= PackedCostDimensionRegistry.dimensionCount(); axis++) {
					assertFalse(certificate.candidateQuantityKnown(candidate, axis));
				}
			}
		}
	}

	private static PackedCostModel model(boolean frontier) {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relation) {
				return 1.0d;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private final FrontierStateArena arena = frontier ? new FrontierStateArena(64L * 1024L) : null;
					private final EvidenceStateRef state = arena == null ? null
							: arena.append(FrontierLayout.of("s", "p", "o"), EvidenceStateSummary.exact(1.0d));

					@Override
					public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
						output.copyCandidateFrom(physical(5.0d, 99.0d));
						if (state != null) {
							output.setEvidenceStateId(state.stateId());
							output.setEvidenceGuarantee(state.summary().guarantee());
							output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
						}
					}

					@Override
					public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relation, context, output);
					}

					@Override
					public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
					}

					@Override
					public FrontierEvidenceBundle detachEvidence(int[] ids) {
						return arena == null ? FrontierEvidenceBundle.empty(ids.length) : arena.exportEvidence(ids);
					}

					@Override
					public void close() {
						if (arena != null) {
							arena.close();
						}
					}
				};
			}
		};
	}

	private static StatementPattern pattern(String name) {
		return patternWithSubject("s", name);
	}

	private static StatementPattern patternWithSubject(String subjectName, String name) {
		return new StatementPattern(new Var(subjectName),
				new Var("p", SimpleValueFactory.getInstance().createIRI("urn:completion-admission:" + name)),
				new Var("o"));
	}

	private static PackedPlanCache.Context context(long revision) {
		return new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, revision);
	}

	private record VectorBoundary(long bytesBeforeGrowth, int fillerCount) {
	}

	private record MemoFixture(PackedMemo memo, int group, int physical, int alternativeMetadata, int child,
			int incumbent) implements AutoCloseable {
		@Override
		public void close() {
			memo.close();
		}
	}
}
